#include <iostream>
#include <string>
#include <algorithm>

int main() {
    int n;
    std::string s;
    std::cin >> n >> s;

    int ins = 0, lon = 0;
    int len = 0;
    for (size_t i = 0; i < s.length(); ++i) {
        if (s[i] == '(') {
            if (len > 0)
                lon = std::max(lon, len);
            len = 0;
            ++i;
            while (i < s.length() && s[i] != ')') {
                if (s[i] == '_') {
                    if (len > 0)
                        ++ins;
                    len = 0;
                } else {
                    ++len;
                }
                ++i;
            }
            if (len > 0)
                ++ins;
            len = 0;
        } else if (s[i] == '_') {
            if (len > 0)
                lon = std::max(lon, len);
            len = 0;
        } else {
            ++len;
        }
    }
    if (len > 0)
        lon = std::max(lon, len);

    std::cout << lon << " " << ins << std::endl;
    return 0;
}
